import java.io.*;
import java.util.*;

public class HeightAllTheSame {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long N = Long.parseLong(st.nextToken());
        long M = Long.parseLong(st.nextToken());
        long L = Long.parseLong(st.nextToken());
        long R = Long.parseLong(st.nextToken());
        br.close();

        long mod = 998244353L;
        long E = (R - L + 1) / 2 + ((R & 1) == 0 && (L & 1) == 0 ? 1 : 0);
        long O = (R - L + 1) - E;
        long nm = N * M;
        long ans;

        if ((nm & 1) == 1) {
            ans = fastPow(E + O, nm, mod);
        } else {
            ans = (fastPow(E + O, nm, mod) + fastPow(E - O, nm, mod)) % mod;
            ans = (ans * fastPow(2, mod - 2, mod)) % mod;
        }
        System.out.println(ans);
    }

    static long fastPow(long x, long k, long mod) {
        if (k == 0) return 1;
        long root = fastPow(x, k / 2, mod);
        long res = (root * root) % mod;
        if ((k & 1) == 1) res = (res * x) % mod;
        return res;
    }
}
